-- products 1440-1520
insert into public.products (
  sku, name, brand_id, category_id, category_path, description,
  price_cents, compare_at_price_cents, stock, cover_path, metadata
)
select
  x->>'sku',
  x->>'name',
  b.id,
  c.id,
  coalesce(array(select jsonb_array_elements_text(x->'category_path')), '{}'),
  coalesce(x->>'description', ''),
  coalesce((x->>'price_cents')::int, 0),
  nullif(x->>'compare_at_price_cents', '')::int,
  coalesce((x->>'stock')::int, 0),
  nullif(x->>'cover_path', ''),
  jsonb_build_object('source', 'cabesto-catalog')
from jsonb_array_elements($json$[{"sku":"SU-0004914","name":"Planche de chasse sous-marine PLUMA BEUCHAT","brand":"BEUCHAT","category_path":["plongee","chasse-sous-marine","signalisation"],"description":"Planche de chasse sous-marine et d'apnée PLUMA BEUCHATLa nouvelle planche de chasse sous marine et d'apnée Pluma Beuchat sert à la fois d'aide de palmage, de bouée de signalisation, de flotteur accroche poisson et de transport pour votre arbalète et matériel de chasse sous-marine. Hydrodynamique, elle assure votre sécurité en surface à petit prix !Constituée d'une enveloppe en nylon haute résistance, le planche de chasse et d'apnée Pluma Beuchat assure votre sécurité en surface notamment grâce à sa couleur rouge. Elle est équipée de trois vessies indépendantes, deux latérales et une centrale ; qui assurent une flottabilité stable et sécurisante, même en pleine mer.La planche est aussi livrée avec deux pavillons montés sur mât, garantissant une bonne visibilité et donc une meilleure sécurité lors des sorties.Elle est conçue pour offrir un véritable confort de nage, notamment lors de longs déplacements grâce à son excellent soutien au palmage. Son coussin central permet non seulement de se reposer facilement en surface, mais améliore également l’hydrodynamisme pour une progression fluide dans l’eau.Pratique pour les chasseurs sous-marins, elle dispose d’un système d’attache ingénieux permettant de fixer jusqu’à deux arbalètes grâce à des crochets solides et des anneaux en caoutchouc.Elle permet également de transporter votre équipement, vos proies avec 8 anneaux d’accrochage d’équipement, 3 anneaux de tractage et de mouillage pouvant aussi servir à l’accrochage d’équipement de chasse sous-marine.Un compartiment de rangement à l’avant fermé par un rabat velcro permet également d'entreposer d'autres accessoires. Des cordons élastiques sur le coussin central sécurisent le matériel du chasseur.La planche de chasse et d'apnée Pluma Beuchat est l'équipement indispensable, fiable et confortable, pensé pour les passionnés d'apnée et de chasse sous-marine exigeants.Informations techniques :Matériau Nylon haute résistanceTransport d'arbalètes 28 anneaux d´accrochage (Ø 40mm)3 anneaux (Ø 50mm) de tractage et de mouillageCouleur RougePoids 1430kgContenu du colis1x planche de chasse et d'apnée PLUMA BEUCHAT, 1x vendu dans un sac mesh réutilisable avec deux pavillons","price_cents":9600,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/SU-0004914/01-pl-10760-pl-10760-picture_1-pl-10760-1.jpg"},{"sku":"SU-0004923","name":"PLAQUETTE DE NATATION HAND PADDLE LARGE SEAC SUB","brand":"SEAC","category_path":["plongee","longe-cote-marche-aquatique","equipement-pour-le-longe-cote"],"description":"PLAQUETTE DE NATATION HAND PADDLE LARGE SEAC SUBNagez avec les plaquettes de nage HAND PADDLE SEAC SUB permettant d'accroître la résistance dans l'eau et ainsi travailler efficacement votre renforcement musculaire.Les palmes pour les mains Seac Hand paddle sont parfaites pour renforcer la partie supérieure du corps pendant la formation de natation. Disponibles en trois tailles, les palmes Seac Hand paddle sont fixées par de souples élastiques qui les tiennent fermement aux mains. De petits trous sur les palettes permettent le passage de l'eau pour une sensation plus naturelle.Accessoires pour les mains idéaux pour la formation des membres supérieurs dans la natation.Palettes perforées pour optimiser la sensation réelle de contact avec l'eau pendant les coups.Dimensions taille L 21 x 16 cm.Élastiques souples réglables et résistants.","price_cents":999,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/SU-0004923/01-hand_paddle_9946bc_01_800.jpg"},{"sku":"SU-0004924","name":"PLAQUETTE DE NATATION HAND PADDLE MEDIUM SEAC SUB","brand":"SEAC","category_path":["plongee","longe-cote-marche-aquatique","equipement-pour-le-longe-cote"],"description":"PLAQUETTE DE NATATION HAND PADDLE MEDIUM SEAC SUBNagez avec les plaquettes de nage HAND PADDLE SEAC SUB permettant d'accroître la résistance dans l'eau et ainsi travailler efficacement votre renforcement musculaire.Les palmes pour les mains Seac Hand paddle sont parfaites pour renforcer la partie supérieure du corps pendant la formation de natation. Disponibles en trois tailles, les palmes Seac Hand paddle sont fixées par de souples élastiques qui les tiennent fermement aux mains. De petits trous sur les palettes permettent le passage de l'eau pour une sensation plus naturelle.Accessoires pour les mains idéaux pour la formation des membres supérieurs dans la natation.Palettes perforées pour optimiser la sensation réelle de contact avec l'eau pendant les coups.Dimensions taille M 19x14.5 cmÉlastiques souples réglables et résistants.","price_cents":999,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/SU-0004924/01-pl-9072-pl-9072-picture_1-pl-9072-1.jpg"},{"sku":"SU-0004925","name":"PLAQUETTE DE NATATION HAND PADDLE SMALL SEAC SUB","brand":"SEAC","category_path":["plongee","longe-cote-marche-aquatique","equipement-pour-le-longe-cote"],"description":"PLAQUETTE DE NATATION HAND PADDLE LARGE SEAC SUBNagez avec les plaquettes de nage HAND PADDLE SEAC SUB permettant d'accroître la résistance dans l'eau et ainsi travailler efficacement votre renforcement musculaire.Les palmes pour les mains Seac Hand paddle sont parfaites pour renforcer la partie supérieure du corps pendant la formation de natation. Disponibles en trois tailles, les palmes Seac Hand paddle sont fixées par de souples élastiques qui les tiennent fermement aux mains. De petits trous sur les palettes permettent le passage de l'eau pour une sensation plus naturelle.Accessoires pour les mains idéaux pour la formation des membres supérieurs dans la natation.Palettes perforées pour optimiser la sensation réelle de contact avec l'eau pendant les coups.Dimensions taille S 17 x 13 cm.Élastiques souples réglables et résistants.","price_cents":999,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/SU-0004925/01-hand_paddle_9946bc_01_800_1.jpg"},{"sku":"SU-0004932","name":"Plombs de chevilles souples la paire 2 x 500 g IMERSION","brand":"IMERSION","category_path":["plongee","plongee-sous-marine","accessoires-de-plongee"],"description":"Plombs de chevilles souples la paire 2 x 500 g IMERSIONUn lestage ergonomique pour une répartition optimale du poids lors de vos sessions de chasse sous-marine ou d'apnée.Les plombs de cheville 2x500g Imersion sont conçus pour offrir un confort maximal et une répartition équilibrée du poids lors de vos plongées.Chaque plomb est fabriqué en grenaille de plomb souple, enveloppé dans une poche en néoprène robuste pour une durabilité accrue.Ces lests permettent d'améliorer l'équilibre et la position sous l'eau, réduisant ainsi la pression sur les hanches et les épaules.Équipés de sangles réglables avec attache rapide en velcro, ils s'adaptent facilement à toutes les tailles de cheville et garantissent un maintien sécurisé.Idéal pour les plongeurs récréatifs et techniques, ce lestage est un choix fiable pour optimiser votre flottabilité et profiter pleinement de vos explorations sous-marines.Caractéristiques Plombs de Cheville 2x500g ImersionFabriqués en grenaille de plomb souple pour une répartition uniformePoche en néoprène robuste pour une durabilité accrueSangles réglables avec attache rapide en velcroAméliore l'équilibre et la position sous l'eauRéduit la pression sur les hanches et les épaulesInformations techniques :MatériauGrenaille de plomb et néoprènePoids2 x 500 gSangleRéglable avec attache rapide en velcroUtilisationLestage des chevillesCompatibilitéPlongée récréative et techniqueContenu du colis1 paire de plombs de cheville 2x500g Imersion avec sangles réglables.","price_cents":2699,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/SU-0004932/01-plombs-de-chevilles-_-clip-2x500gr-imersion_yiomxi0rhxgnswwb.jpg"},{"sku":"SU-0005331","name":"Plomb de ceinture brut de 500 g LEMER","brand":"LEMER","category_path":["plongee"],"description":"détaillée 5,99 € 6,00 € Quantité Ajouter au panier En stock (1) Livraison estimée entre le 15/10/2026 et le 19/10/2026 Selon le mode de livraison choisi et les délais du transporteur. Vérifie la disponibilité... Vérifier la disponibilité dans votre magasin Livraison express en France Métropolitaine Paiement 100% sécurisé 30 jours pour changer d'avis Paiement en 3x, 4x ou 10x avec Floa Sous réserve d’acceptation par Floa. Vous disposez du délai légal de rétractation. AVIS CLIENTS 5 / 5 Basé sur 1 avis soumis à un contrôle Voir tous les avis sur ce site 5 étoiles 1 4 étoiles 0 3 étoiles 0 2 étoiles 0 1 étoile 0 Trier les avis Les plus récents Les plus anciens Notes les plus élevées Notes les plus basses Les plus utiles 5/5 Avis vérifié Nickel Avis du 28/11/2020 , suite à une expérience du 10/11/2020 par A.A. Utile (0) Signaler","price_cents":599,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/SU-0005331/01-pl-6151-pl-6151-picture_1-pl-6151-1.jpg"},{"sku":"SU-0005341","name":"Plomb plat universel pour baudrier de chasse sous-marine 650 g IMERSION","brand":"IMERSION","category_path":["plongee","plongee-sous-marine","accessoires-de-plongee"],"description":"Plombs 650 gr pour Baudrier Imersion : équilibre et confort pour vos plongéesUn lestage pratique et efficace pour une répartition optimale du poids dans votre baudrier de chasse sous-marine.Les plombs 650 gr pour baudrier Imersion sont spécialement conçus pour offrir un équilibre parfait et un confort optimal lors de vos plongées.Fabriqués en plomb de haute qualité, ces lests s'intègrent facilement dans les compartiments des baudriers, garantissant une répartition uniforme du poids.Leur design compact et plat permet une insertion aisée et un ajustement précis, idéal pour les plongeurs récréatifs et techniques.Avec des dimensions de 8 x 8 cm et une épaisseur de 1 cm, ces plombs s'adaptent parfaitement aux baudriers IMERSION, tels que les modèles CE614 et CE615, comme à tous les baudriers de chasse sous-marine avec poches.Robustes et durables, ils résistent à l'usure et aux conditions exigeantes sous l'eau.Les plombs 650 gr pour baudrier Imersion sont un choix fiable pour améliorer votre flottabilité et profiter pleinement de vos explorations sous-marines.Caractéristiques Plombs 650 gr pour Baudrier ImersionFabriqués en plomb de haute qualité pour une durabilité accrueDimensions compactes de 8 x 8 cm pour une insertion facileÉpaisseur de 1 cm pour un ajustement précisCompatibles avec tous les baudriers à poches du marchéIdéal pour une répartition uniforme du poidsInformations techniques :MatériauPlombPoids650 gDimensions8 x 8 cmÉpaisseur1 cmCompatibilitéTous les baudriers néoprène de chasse sous-marineContenu du colis1 x plomb 650 gr pour baudrier IMERSION.","price_cents":1399,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/SU-0005341/01-plomb-650-gr-pour-baudrier-imersion-p-image-29043-grande_e1v8hwd6nz1jphho.jpg"},{"sku":"SU-0005369","name":"Poche à plomb pour gilet stab X-ONE et X-BLACK SCUBAPRO","brand":"SCUBAPRO","category_path":["plongee"],"description":"Poches à plomb pour stab X-One et X-black de Scubapro, vendues par paire et sans lest.","price_cents":5699,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/SU-0005369/01-pl-8205-pl-8205-picture_1-pl-8205-1.jpg"},{"sku":"SU-0005383","name":"Poche à plomb pour gilet stab SLS MARES","brand":"MARES","category_path":["plongee","plongee-sous-marine","gilets-stabilisateurs"],"description":"Mares présente un nouveau système de lestage intégré pour les gilets stabilisateurs. Celui-ci apparaît pour la première fois sur le nouveau gilet stabilisateur Quantum, il résulte d'années d'études visant à créer un système de lest plus sûr et plus facile d'utilisation.Le rôle d'un système de lestage est d'effectuer deux tâches seulement, mais sans erreur : tout d'abord, le largage accidentel d'une poche de lest doit être évité. Ensuite, en cas d'urgence, le plongeur doit pouvoir se débarrasser des poches de lest d'une façon simple et intuitive, même en cas de stress et de panique.En plus de ces deux aspects principaux, cela ne fait certainement pas de mal si le système est simple d'utilisation, montre clairement s'il est engagé ou pas, reste bien stable sur le gilet, a suffisamment de capacité pour l'utilisation attendue, et vous permet même de personnaliser les poches de lest.Tous ces aspects ont été soigneusement analysés au cours de la phase de développement du SLS (brevet en cours). Regardons un peu le mécanisme de fermeture. Au lieu de reposer sur des éléments élastiques dont l'état de déformation définit si le système est engagé ou non, le SLS se base sur des mouvements mécaniques et sur des interférences. La base du système est un curseur qui peut glisser dans la poignée, et son mouvement définit la position de la \" dent \" sur la partie mâle de la boucle. Lorsque le curseur est poussé vers l'intérieur, il enfonce la \" dent \" vers l'extérieur et la bloque contre la \" dent \"correspondante de la boucle femelle, en bloquant la voie de retour. Lorsque la poignée est déverrouillée, elle tire le curseur et par conséquence ouvre mécaniquement la \" dent \" vers l'intérieur par un système de guides et de pistes, et libère ainsi la boucle femelle. Cela nous donne un système qui résiste à tout, mais qui se libère en tirant simplement la poignée, sans possibilité d'erreur ou que quelque chose reste accroché.La facilité d'utilisation est garantie par la large poignée et par un tunnel sur le gilet qui guide l'insertion de la poche à lest, afin que la boucle mâle arrive bien en ligne par rapport à la pièce femelle. Tout en maintenant la poignée contre la boucle femelle, utilisez un doigt pour pousser le curseur et bloquer la poche en place. Vous entendrez un son signalant que l'opération est effectuée, ce que vous constaterez également visuellement. Une petite fenêtre affiche un cadenas ouvert sur un fond rouge lorsque le système est ouvert, et un cadenas fermé sur un fond vers lorsqu'il est bloqué. C'est une nouveauté dans le domaine du lestage, qui attirera certainement beaucoup d'attention. D'une part, votre coéquipier pourra immédiatement vérifier l'insertion correcte ou incorrecte de votre système de lestage, simplement en vous regardant.Le système de poignée et de boucle est raccordé à la poche de lest à l'aide d'un élément semi-rigide en forme de U, maintenu en place par une broche. Cela élimine tout mouvement relatif qui pourrait se produire entre la boucle et la poche, puis entre la poche et le gilet (donc, plus de poches à lest à moitié sorties du gilet). Cela s'associe au tunnel qui maintient l'ensemble de la poche parfaitement en place, et vous obtenez un positionnement très stable du lest sur le gilet. La poche elle-même existe en deux tailles, contenant un maximum de 6 kg/12 livres ou 4 kg/8 livres. Les deux tailles possèdent une fermeture à glissière renforcée ainsi qu'une nouvelle idée bien utile : une étiquette sur laquelle vous pouvez indiquer vos initiales ou d'autres marques d'identification avec un marqueur permanent.","price_cents":6400,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/SU-0005383/01-pl-10610-pl-10610-picture_1-pl-10610-1.jpg"},{"sku":"SU-0005384","name":"Poche à plomb pour gilet stab SLS MARES","brand":"MARES","category_path":["plongee","plongee-sous-marine","gilets-stabilisateurs"],"description":"Mares présente un nouveau système de lestage intégré pour les gilets stabilisateurs. Celui-ci apparaît pour la première fois sur le nouveau gilet stabilisateur Quantum, il résulte d'années d'études visant à créer un système de lest plus sûr et plus facile d'utilisation.Le rôle d'un système de lestage est d'effectuer deux tâches seulement, mais sans erreur : tout d'abord, le largage accidentel d'une poche de lest doit être évité. Ensuite, en cas d'urgence, le plongeur doit pouvoir se débarrasser des poches de lest d'une façon simple et intuitive, même en